export interface RoadmapSource {
  title: string;
  uri: string;
}

export interface RoadmapResult {
  content: string;
  sources: RoadmapSource[];
}

export interface WeekPlan {
  week: number;
  objective: string;
  days: {
    day: string;
    topic: string;
    description: string;
  }[];
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { RoadmapResult, RoadmapSource } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async generateRoadmap(topic: string): Promise<RoadmapResult> {
    const prompt = `Create a highly structured 4-week learning roadmap for the topic: "${topic}". 
    The roadmap should be tailored for a beginner-to-intermediate level.

    For each week:
    1. Define a clear objective.
    2. Provide a day-by-day breakdown (Day 1 to Day 7) with specific sub-topics and a one-sentence explanation for each.
    3. Suggest at least 2 high-quality online resources (YouTube channels, blogs, or documentation).

    Format the output in clear Markdown with bold headers for weeks and bullet points for days. 
    Make the tone professional, encouraging, and actionable.`;

    try {
      const response: GenerateContentResponse = await this.ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
        },
      });

      const text = response.text || "No roadmap generated.";

      // Extract grounding sources
      const sources: RoadmapSource[] = [];
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

      if (chunks) {
        chunks.forEach((chunk: any) => {
          if (chunk.web) {
            sources.push({
              title: chunk.web.title,
              uri: chunk.web.uri
            });
          }
        });
      }

      // De-duplicate sources
      const uniqueSources = Array.from(new Set(sources.map(s => s.uri)))
        .map(uri => sources.find(s => s.uri === uri)!)
        .slice(0, 6);

      return {
        content: text,
        sources: uniqueSources,
      };
    } catch (error) {
      console.error("Gemini API Error:", error);
      throw new Error("Failed to generate your learning roadmap. Please try again later.");
    }
  }
}

export const geminiService = new GeminiService();

import React from 'react';

interface MarkdownRendererProps {
  content: string;
}

export const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({ content }) => {
  // Simple markdown-to-JSX converter for basic formatting
  const lines = content.split('\n');

  return (
    <div className="prose prose-slate max-w-none">
      {lines.map((line, idx) => {
        if (line.startsWith('### ')) {
          return <h3 key={idx} className="text-xl font-bold text-slate-800 mt-6 mb-3">{line.replace('### ', '')}</h3>;
        }
        if (line.startsWith('## ')) {
          return <h2 key={idx} className="text-2xl font-bold text-slate-900 mt-8 mb-4 border-b pb-2 border-indigo-100">{line.replace('## ', '')}</h2>;
        }
        if (line.startsWith('# ')) {
          return <h1 key={idx} className="text-3xl font-extrabold text-indigo-700 mb-6">{line.replace('# ', '')}</h1>;
        }
        if (line.startsWith('**Week')) {
            return <div key={idx} className="bg-indigo-50 p-4 rounded-lg my-6 border-l-4 border-indigo-600"><span className="text-xl font-bold text-indigo-900">{line.replace(/\*\*/g, '')}</span></div>;
        }
        if (line.startsWith('- ') || line.startsWith('* ')) {
          return <li key={idx} className="ml-4 mb-2 text-slate-700 list-disc">{line.replace(/^[-*]\s/, '')}</li>;
        }
        if (line.trim() === '') {
          return <div key={idx} className="h-2" />;
        }

        // Bold parsing
        const formattedLine = line.split(/(\*\*.*?\*\*)/).map((part, i) => {
          if (part.startsWith('**') && part.endsWith('**')) {
            return <strong key={i} className="font-semibold text-slate-900">{part.slice(2, -2)}</strong>;
          }
          return part;
        });

        return <p key={idx} className="text-slate-600 leading-relaxed mb-1">{formattedLine}</p>;
      })}
    </div>
  );
};

