    e.preventDefault();
    if (!topic.trim()) return;

    setLoading(true);
    setError(null);
    setCurrentTopic(topic);

    try {
      const result = await geminiService.generateRoadmap(topic);
      setRoadmap(result);
    } catch (err: any) {
      setError(err.message || 'Something went wrong');
    } finally {
      setLoading(false);
    }
  }, [topic]);

  return (
    <Layout>
      <div className="max-w-4xl mx-auto px-4 py-12">
        {/* Hero Section */}
        <div className="text-center mb-12">
          <h2 className="text-4xl md:text-5xl font-extrabold text-slate-900 tracking-tight mb-4">
            Forge Your Learning <span className="text-indigo-600">Roadmap</span>
          </h2>
          <p className="text-lg text-slate-600 max-w-2xl mx-auto">
            Transform any topic into a structured 4-week mastery plan. Powered by AI and real-world web research.
          </p>
        </div>

        {/* Input Form */}
        <div className="max-w-2xl mx-auto mb-16">
          <form onSubmit={handleSubmit} className="relative group">
            <div className="absolute -inset-1 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-2xl blur opacity-25 group-focus-within:opacity-50 transition duration-1000"></div>
            <div className="relative flex flex-col md:flex-row gap-2">
              <div className="relative flex-grow">
                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-400">
                  <i className="fas fa-search"></i>
                </div>
                <input
                  type="text"
                  value={topic}
                  onChange={(e) => setTopic(e.target.value)}
                  placeholder="e.g. Digital Marketing, Quantum Physics, Figma Design..."
                  className="block w-full pl-11 pr-4 py-4 bg-white border border-slate-200 rounded-2xl text-slate-900 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent shadow-sm transition-all"
                />
              </div>
              <button
                type="submit"
                disabled={loading || !topic.trim()}
                className="bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 text-white font-bold py-4 px-8 rounded-2xl transition-all shadow-lg hover:shadow-indigo-200 flex items-center justify-center gap-2 shrink-0"
              >
                {loading ? (
                  <>
                    <i className="fas fa-spinner fa-spin"></i>
                    Generating...
                  </>
                ) : (
                  <>
                    Build Path
                    <i className="fas fa-arrow-right"></i>
                  </>
                )}
              </button>
            </div>
          </form>

          {/* Suggested Topics */}
          {!roadmap && !loading && (
            <div className="mt-6 flex flex-wrap justify-center gap-2">
              <span className="text-sm text-slate-500 mr-2">Try:</span>
              {['Prompt Engineering', 'Classical Piano', 'UI Design', 'Blockchain'].map((t) => (
                <button
                  key={t}
                  onClick={() => { setTopic(t); }}
                  className="text-xs font-medium bg-slate-100 hover:bg-indigo-50 text-slate-600 hover:text-indigo-600 px-3 py-1.5 rounded-full border border-slate-200 hover:border-indigo-200 transition-all"
                >
                  {t}
