              ))}
            </div>
          )}
        </div>

        {/* Main Content Area */}
        {error && (
          <div className="bg-red-50 border border-red-200 text-red-700 px-6 py-4 rounded-2xl flex items-center gap-3 mb-8">
            <i className="fas fa-exclamation-circle text-xl"></i>
