import React from 'react';

interface MarkdownRendererProps {
  content: string;
}

export const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({ content }) => {
  const lines = content.split('\n');

  return (
    <div className="space-y-4">
      {lines.map((line, idx) => {
        const trimmed = line.trim();

        // Main Title
        if (trimmed.startsWith('# ')) {
          return (
            <h1 key={idx} className="text-3xl font-black text-slate-900 mb-8 border-b-4 border-indigo-500 pb-2 inline-block">
              {trimmed.replace('# ', '')}
            </h1>
          );
        }

        // Weekly Section
        if (trimmed.startsWith('## Week')) {
          return (
            <div key={idx} className="mt-12 mb-6 sticky top-16 z-20 bg-white/80 backdrop-blur-md py-2 border-b border-slate-100">
              <h2 className="text-2xl font-bold text-indigo-700 flex items-center gap-3">
                <span className="bg-indigo-600 text-white px-3 py-1 rounded-lg text-sm font-black uppercase tracking-widest">
                  {trimmed.split(':')[0].replace('## ', '')}
                </span>
                <span className="text-slate-800">{trimmed.split(':')[1]?.trim()}</span>
              </h2>
            </div>
          );
        }

        // Daily Cards
        if (trimmed.startsWith('### Day')) {
          const dayTitle = trimmed.replace('### ', '');
          const [dayLabel, ...goalParts] = dayTitle.split(':');
          const goal = goalParts.join(':').replace(/Goal:?/i, '').trim();

          return (
            <div key={idx} className="bg-white border border-slate-200 rounded-xl p-5 shadow-sm hover:shadow-md transition-shadow mb-4">
              <div className="flex flex-col md:flex-row md:items-center gap-2 mb-3">
                <span className="text-indigo-600 font-bold uppercase text-xs tracking-widest">
                  {dayLabel}
                </span>
                {goal && (
                  <span className="bg-indigo-50 text-indigo-700 text-sm font-semibold px-3 py-1 rounded-full border border-indigo-100 flex items-center gap-2">
                    <i className="fas fa-bullseye text-[10px]"></i>
                    Goal: {goal}
                  </span>
                )}
              </div>
              <div className="text-slate-600 text-sm leading-relaxed" id={`desc-${idx}`}>
                {/* Content will follow in subsequent lines */}
              </div>
            </div>
          );
        }

        // Normal text or bullets (simplified for this custom structure)
        if (trimmed.startsWith('- ') || trimmed.startsWith('* ')) {
          return (
            <li key={idx} className="ml-6 text-slate-600 list-disc mb-2 marker:text-indigo-400">
              {trimmed.replace(/^[-*]\s/, '')}
            </li>
          );
        }

        if (trimmed === '' || trimmed === '## Resources') return null;

        // Bold parsing for standard paragraphs
        const formattedLine = trimmed.split(/(\*\*.*?\*\*)/).map((part, i) => {
          if (part.startsWith('**') && part.endsWith('**')) {
            return <strong key={i} className="font-bold text-slate-800">{part.slice(2, -2)}</strong>;
          }
          return part;
        });

        return (
          <p key={idx} className="text-slate-600 leading-relaxed mb-4">
            {formattedLine}
          </p>
        );
      })}
    </div>
  );
};

